const body = $input.first().json.body || $input.first().json || {};

const hasImage = !!(body.imageFindingsText || body.imageUrl || body.imageBase64);
const hasAudio = !!(body.audioTranscript || body.audioMockText || body.audioUrl);

if (!body.patientId || !hasImage || !hasAudio) {
  return [{ json: { valid: false, statusCode: 400, error: 'Se requiere patientId, una imagen o descripcion visual, y un audioUrl o audioTranscript.' } }];
}

const hashId = (id) => {
  let h = 0;
  const value = String(id);
  for (let i = 0; i < value.length; i++) {
    h = ((h << 5) - h) + value.charCodeAt(i);
    h |= 0;
  }
  return 'hash_' + Math.abs(h).toString(36);
};

return [{
  json: {
    valid: true,
    patientHash: hashId(body.patientId),
    imageStudyType: body.imageStudyType || 'estudio_no_especificado',
    imageFindingsText: String(body.imageFindingsText || '').trim(),
    imageUrl: body.imageUrl || null,
    audioTranscript: String(body.audioTranscript || '').trim(),
    audioMockText: String(body.audioMockText || '').trim(),
    audioUrl: body.audioUrl || null,
    audioLanguage: body.audioLanguage || 'es',
    topK: Number(body.topK || 3),
    startedAtMs: Date.now()
  }
}];

const prev = $('Validar y normalizar').first().json;
const echo = $input.first().json || {};
const payload = echo.json || {};
const text = String(payload.findings || prev.imageFindingsText || '').toLowerCase();

const labels = [];
let suspectedFinding = 'sin hallazgo concluyente';
if (text.includes('infiltrado')) {
  labels.push('infiltrado_pulmonar');
  suspectedFinding = 'posible proceso infeccioso';
}
if (text.includes('opacidad')) labels.push('opacidad');
if (text.includes('derrame')) labels.push('derrame_pleural');
if (text.includes('nodulo')) labels.push('nodulo');
if (text.includes('fractura')) suspectedFinding = 'hallazgo oseo traumatico';

const apiOk = Object.keys(echo).length > 0;
return [{
  json: {
    ...prev,
    imageApi: {
      requestOk: apiOk,
      provider: 'postman-echo-mock',
      retriesPlanned: 3
    },
    imageAnalysis: {
      studyType: prev.imageStudyType,
      labels,
      suspectedFinding,
      confidence: apiOk ? (labels.length ? 0.84 : 0.55) : 0.2,
      source: apiOk ? 'simulated-image-service' : 'image-fallback'
    }
  }
}];

const d = $input.first().json;
const transcript = String(d.audioTranscript || d.audioMockText || '').replace(/\s+/g, ' ').trim();
return [{
  json: {
    ...d,
    stt: {
      transcript,
      source: 'provided-transcript',
      language: d.audioLanguage,
      confidence: transcript.length > 80 ? 0.92 : transcript.length > 25 ? 0.74 : 0.46,
      quality: transcript.length > 80 ? 'alta' : transcript.length > 25 ? 'media' : 'baja',
      unresolvedAudio: transcript.length === 0,
      provider: 'manual-or-upstream'
    }
  }
}];

const prev = $('Parse imagen').first().json;
const data = $input.first().json || {};
const transcript = String(data.text || '').replace(/\s+/g, ' ').trim();
const completed = data.status === 'completed' && transcript.length > 0;
return [{
  json: {
    ...prev,
    stt: {
      transcript,
      source: completed ? 'assemblyai' : 'stt-fallback',
      language: prev.audioLanguage,
      confidence: completed ? 0.88 : 0.2,
      quality: completed ? 'alta' : 'baja',
      unresolvedAudio: !completed,
      provider: 'AssemblyAI',
      transcriptId: data.id || null,
      status: data.status || 'unavailable'
    }
  }
}];

const d = $input.first().json;
const transcript = String(d.stt.transcript || '').trim();
const sentences = transcript.split(/(?<=[.!?])\s+/).map((s) => s.trim()).filter(Boolean);
const chunks = [];
let current = '';
let idx = 1;
for (const sentence of sentences) {
  if ((current + ' ' + sentence).trim().length <= 220) {
    current = (current + ' ' + sentence).trim();
  } else {
    if (current) chunks.push({ chunkId: 'chunk_' + idx++, text: current, charCount: current.length });
    current = sentence;
  }
}
if (current) chunks.push({ chunkId: 'chunk_' + idx++, text: current, charCount: current.length });
if (chunks.length === 0 && transcript) chunks.push({ chunkId: 'chunk_1', text: transcript, charCount: transcript.length });

const knowledgeBase = [
  { docId: 'doc_1', title: 'Guia de neumonia adquirida en la comunidad', text: 'Infiltrado en radiografia de torax, fiebre, tos y disnea requieren correlacion clinica, seguimiento cercano y evaluacion de saturacion.' },
  { docId: 'doc_2', title: 'Checklist de informe radiologico toracico', text: 'Opacidades, derrame pleural y nodulos deben documentarse con lateralidad, extension y necesidad de control por imagen.' },
  { docId: 'doc_3', title: 'Protocolo de seguimiento ambulatorio respiratorio', text: 'Pacientes con disnea progresiva, fiebre o saturacion menor a 94 requieren control en menos de 24 horas y eventual derivacion.' },
  { docId: 'doc_4', title: 'Guia de comunicacion clinica segura', text: 'Los resumenes automaticos deben marcar incertidumbre, pedir revision humana y evitar recomendaciones diagnosticas definitivas.' }
];

const queryText = [d.stt.transcript, d.imageFindingsText, d.imageAnalysis.labels.join(' '), d.imageAnalysis.suspectedFinding].join(' ');
const embedTexts = [queryText, ...knowledgeBase.map((doc) => doc.text)];

return [{
  json: {
    ...d,
    chunking: {
      strategy: 'sentence-window-no-overlap',
      chunkCount: chunks.length,
      maxChunkChars: 220
    },
    chunks,
    knowledgeBase,
    embeddingTexts: embedTexts
  }
}];

const d = $('Chunking y base clinica').first().json;
const embedResponse = $input.first().json || {};

const normalize = (text) => String(text || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
const dims = 64;
const fallbackEmbed = (text) => {
  const vec = new Array(dims).fill(0);
  for (const token of normalize(text).split(' ')) {
    if (!token) continue;
    let hash = 0;
    for (let i = 0; i < token.length; i++) hash = ((hash << 5) - hash) + token.charCodeAt(i);
    vec[Math.abs(hash) % dims] += 1;
  }
  const norm = Math.sqrt(vec.reduce((acc, n) => acc + (n * n), 0)) || 1;
  return vec.map((n) => n / norm);
};
const cosine = (a, b) => a.reduce((acc, n, i) => acc + (n * b[i]), 0);

let embeddings = embedResponse?.embeddings?.float || null;
let embeddingSource = 'cohere';
if (!Array.isArray(embeddings) || embeddings.length !== d.embeddingTexts.length) {
  embeddings = d.embeddingTexts.map((text) => fallbackEmbed(text));
  embeddingSource = 'local-fallback';
}

const queryVector = embeddings[0];
const docVectors = embeddings.slice(1);
const documents = d.knowledgeBase.map((doc, index) => ({
  docId: doc.docId,
  title: doc.title,
  excerpt: doc.text,
  score: Number(cosine(queryVector, docVectors[index]).toFixed(4))
})).sort((a, b) => b.score - a.score).slice(0, d.topK || 3);

const summary = {
  brief: [
    d.stt.transcript ? ('Voz: ' + d.stt.transcript) : 'Sin transcripcion confiable.',
    d.imageAnalysis.labels.length ? ('Imagen: ' + d.imageAnalysis.labels.join(', ')) : 'Imagen sin etiquetas fuertes.',
    documents[0] ? ('Documento mas cercano: ' + documents[0].title) : 'Sin soporte documental.'
  ].join(' '),
  assessment: d.imageAnalysis.suspectedFinding,
  followUp: documents[0] && documents[0].score >= 0.55 ? 'Se recomienda correlacion clinica y revision profesional dentro del circuito habitual.' : 'La evidencia recuperada es debil y requiere revision humana.',
  requiresHumanReview: !documents[0] || documents[0].score < 0.7 || d.stt.confidence < 0.7 || d.imageAnalysis.confidence < 0.6
};

return [{
  json: {
    ...d,
    retrieval: {
      strategy: embeddingSource === 'cohere' ? 'cohere-embeddings-cosine' : 'hashed-bow-cosine',
      embeddingSource,
      topK: documents.length,
      documents,
      topScore: documents[0] ? documents[0].score : 0
    },
    summary
  }
}];

const d = $input.first().json;
const transcriptQuality = d.stt.unresolvedAudio ? 0.1 : Number(d.stt.confidence.toFixed(2));
const imageConfidence = Number(d.imageAnalysis.confidence.toFixed(2));
const groundingScore = Number((Math.max(0, d.retrieval.topScore) * 1.2).toFixed(2));
const overallScore = Number(((transcriptQuality * 0.35) + (imageConfidence * 0.25) + (groundingScore * 0.4)).toFixed(2));
const reasons = [];
if (!d.imageApi.requestOk) reasons.push('image_api_failed');
if (d.stt.unresolvedAudio) reasons.push('stt_unresolved');
if (d.retrieval.topScore < 0.45) reasons.push('weak_grounding');
if (overallScore < 0.6) reasons.push('overall_below_threshold');

return [{
  json: {
    ...d,
    evaluation: {
      transcriptQuality,
      imageConfidence,
      groundingScore,
      overallScore,
      passed: reasons.length === 0,
      reasons
    }
  }
}];

const d = $('Evaluacion automatica').first().json;
return [{
  json: {
    ...d,
    fallbackUsed: true,
    summary: {
      brief: 'No se pudo validar con suficiente confianza la combinacion de voz e imagen. Se requiere revision humana antes de reutilizar este contenido.',
      assessment: 'fallback_seguro',
      followUp: 'Verificar imagen, reescuchar audio y confirmar contexto clinico.',
      requiresHumanReview: true
    },
    tts: {
      provider: 'ElevenLabs-opcional',
      text: 'No se pudo validar con confianza el contenido multimodal. Se requiere revision humana.'
    }
  }
}];

const d = $input.first().json;
const now = Date.now();
const latencyMs = d.startedAtMs ? now - d.startedAtMs : null;
return [{
  json: {
    patientHash: d.patientHash,
    imageAnalysis: d.imageAnalysis,
    stt: d.stt,
    chunking: d.chunking,
    chunks: d.chunks,
    retrieval: d.retrieval,
    summary: d.summary,
    evaluation: d.evaluation,
    tts: d.tts || {
      provider: 'ElevenLabs-opcional',
      text: d.summary.followUp
    },
    log: {
      event: 'biomedical_multimodal_completed',
      ts: new Date(now).toISOString(),
      latencyMs,
      fallbackUsed: d.fallbackUsed === true,
      topScore: d.retrieval.topScore,
      overallScore: d.evaluation.overallScore,
      requiresHumanReview: d.summary.requiresHumanReview,
      studyType: d.imageStudyType,
      embeddingSource: d.retrieval.embeddingSource,
      sttProvider: d.stt.provider
    }
  }
}];
